//! Messages for the copy of the old system disk an upgrade keeps, and the loud warning that comes with a store the upgrade
//! cannot keep (English first), looked up by `messages::t`.

pub const EN: &[(&str, &str)] = &[
    ("old_disk.head_lost", "SECRETS STORE WILL BE LOST. {box} keeps its store's key in a file on its system disk, and nothing else holds a copy. This upgrade replaces that disk, so the new machine cannot open the store: it starts a new, empty one, and the old store is set aside (renamed, never deleted). What you will have to enter again: {lost}."),
    ("old_disk.head_unknown", "SECRETS STORE MAY BE LOST. ozbox could not confirm that {box}'s store will open after this upgrade, and it does not guess: what the box says about itself is not trusted, and its own program is too old to tell the box's root where the store's key is. If the key is a file on the system disk (it is, on a box made without the fleet's KMS key), this upgrade destroys it and the box starts a new, empty store. What you would have to enter again: {lost}."),
    ("old_disk.kept", "A copy of the old system disk is kept first, so the key is not destroyed with it: an encrypted snapshot of that disk, tagged ozbox-purpose=pre-upgrade-root, taken before anything is stopped. Its id is in the report when the upgrade finishes, and `ozbox backup list {box}` shows it at any time. It holds the old store's key file, so it can reopen the old store (docs: Recovering an old secrets store). It is billed like any EBS snapshot (by what it stores), and nothing deletes it for you: when your keys are entered again and `ozbox adopt-fleet-key {box}` has moved the store to the fleet's KMS key, delete it with `ozbox backup delete {box} <snapshot id>`."),
    ("old_disk.opted_out", "No copy of the old system disk is kept (--no-pre-upgrade-snapshot): the key is destroyed with the old disk, and the old store can never be opened again."),
    ("old_disk.unavailable", "No copy of the old system disk can be kept on this provider: the key is destroyed with the old disk, and the old store can never be opened again."),
    ("old_disk.afterwards", "Afterwards, enter the keys again (`ozbox secrets import <file> --project <project> --env <env> --box {box}`, and the other items above), then run `ozbox adopt-fleet-key {box}` so every later upgrade keeps the store (it needs the fleet's KMS key set under [aws]: `ozbox init` writes it)."),
    ("old_disk.taken", "A copy of the old system disk of {box} is kept: snapshot {id} (encrypted, tagged ozbox-purpose=pre-upgrade-root). It holds the old store's key file. To reopen the old store, see the docs (Recovering an old secrets store). When it is no longer needed, delete it: `ozbox backup delete {box} {id}`. `ozbox destroy {box}` deletes it too, unless you pass --keep-old-system-disks."),
    ("old_disk.not_found", "A copy of the old system disk of {box} was taken, but the apply did not report its id ({why}). `ozbox backup list {box}` lists it (it is marked as the root disk, not /work)."),
    ("old_disk.taking", "Taking the copy of the old system disk of {box} first, before anything is stopped. A first copy can take several minutes; it keeps going by itself if this gives up."),
    ("old_disk.not_taken", "No copy of the old system disk of {box} was kept, as the plan said."),
];
